package com.jnapanam.sportszone.identity.model;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity@Table(name="password_reset_tokens")public class PasswordResetToken{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private User user;@Column(name="token_hash",nullable=false,unique=true,length=64)private String tokenHash;@Column(name="expires_at",nullable=false)private Instant expiresAt;@Column(name="used_at")private Instant usedAt;@Column(name="created_at",nullable=false)private Instant createdAt;protected PasswordResetToken(){}public PasswordResetToken(User user,String hash,Instant expiry){id=UUID.randomUUID();this.user=user;tokenHash=hash;expiresAt=expiry;createdAt=Instant.now();}public boolean usable(){return usedAt==null&&expiresAt.isAfter(Instant.now())&&user.isActive();}public void use(){usedAt=Instant.now();}public User getUser(){return user;}}
